export default function MenuCard({ item, addToCart }) {
  const out = item.stock <= 0;

  return (
    <div className={`menu-card ${out ? "out" : ""}`}>
      <h3>{item.name}</h3>
      <p>₹{item.price}</p>

      <p className="stock">
        {out ? "Out of stock" : `Stock: ${item.stock}`}
      </p>

      <button
        disabled={out}
        onClick={() => addToCart(item)}
      >
        {out ? "Unavailable" : "Add"}
      </button>
    </div>
  );
}
